// src/components/blog/BlogPost.js
import React from 'react';
import styles from '../../styles/pages/Blog.module.css';

/**
 * Blog post component that displays a single post with title, date and content
 * Tags are displayed at the bottom after content
 * Description is commented out but preserved in the code for future use
 * 
 * @param {Object} props - Component props
 * @param {string} props.id - Unique post identifier
 * @param {string} props.title - Post title
 * @param {string} props.date - Post date
 * @param {string} props.description - Post description (not displayed currently)
 * @param {Array} props.tags - Post tags
 * @param {string} props.content - Post content (without metadata)
 */
export function BlogPost({ id, title, date, description, tags = [], content }) {
  return (
    <div id={`post-${id}`} className={styles.post}>
      <div className={styles.postHeader}>
        <h2>{title}</h2>
        <span className={styles.postDate}>{date}</span>
      </div>
      
      {/* Description is commented out but preserved for future use
      {description && (
        <p className={styles.postDescription}>{description}</p>
      )}
      */}
      
      <div className={styles.postContent}>
        {content}
      </div>
      
      {/* Tags moved to bottom of post */}
      {tags && tags.length > 0 && (
        <div className={styles.tagContainer}>
          {tags.map((tag, index) => (
            <span key={index} className={styles.tag}>{tag}</span>
          ))}
        </div>
      )}
    </div>
  );
}