import React, { useState, useEffect } from 'react';
import styles from '../../styles/pages/Resume.module.css';

/**
 * Sticky sidebar navigation for resume page that remains visible while scrolling
 * 
 * @param {Object} props - Component props
 * @param {Array} props.links - Array of link objects with id and label
 */
export function ResumeSidebar({ links }) {
  const [activeSection, setActiveSection] = useState('');

  // Effect to track scroll position and update active section
  useEffect(() => {
    const sectionElements = links.map(link => 
      document.getElementById(link.id)
    ).filter(Boolean);
    
    const handleScroll = () => {
      const scrollPosition = window.scrollY + 100; // Offset for better UX
      
      // Find the current active section based on scroll position
      const currentSection = sectionElements.find(section => {
        if (!section) return false;
        const sectionTop = section.offsetTop;
        const sectionBottom = sectionTop + section.offsetHeight;
        return scrollPosition >= sectionTop && scrollPosition < sectionBottom;
      });
      
      if (currentSection) {
        setActiveSection(currentSection.id);
      }
    };
    
    // Add scroll event listener
    window.addEventListener('scroll', handleScroll);
    // Initial check
    handleScroll();
    
    // Clean up
    return () => window.removeEventListener('scroll', handleScroll);
  }, [links]);
  
  // Handle smooth scrolling when clicking a link
  const handleLinkClick = (e, targetId) => {
    e.preventDefault();
    const targetElement = document.getElementById(targetId);
    
    if (targetElement) {
      window.scrollTo({
        top: targetElement.offsetTop - 20, // Small offset for better positioning
        behavior: 'smooth'
      });
      setActiveSection(targetId);
    }
  };

  return (
    <aside className={styles.resumeSidebar}>
      <div className={styles.sidebarContent}>
        <h3>Table of Contents</h3>
        <nav className={styles.sidebarNav}>
          {links.map((link) => (
            <a 
              key={link.id} 
              href={`#${link.id}`}
              className={`${styles.sidebarLink} ${activeSection === link.id ? styles.sidebarLinkActive : ''}`}
              onClick={(e) => handleLinkClick(e, link.id)}
            >
              {link.label}
            </a>
          ))}
        </nav>
      </div>
    </aside>
  );
}
