import React, { useState, useEffect } from "react";
import styles from "../styles/pages/Blog.module.css";
import { BlogPost, Pagination, TableOfContents } from "../components";
import { fetchPosts } from "../utils/postUtils";

/**
 * Blog page component that displays blog posts with pagination
 * Uses reusable components for blog posts, pagination, and table of contents
 * Layout structure updated to match resume page for consistency
 * Enhanced with better error handling for GitHub Pages deployment
 */
export const Blog = () => {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [currentPage, setCurrentPage] = useState(0);
  const POSTS_PER_PAGE = 5;

  // Fetch posts from /public/posts directory on component mount
  useEffect(() => {
    const loadPosts = async () => {
      try {
        setLoading(true);
        const data = await fetchPosts();
        if (data.length > 0) {
          setPosts(data);
          setError(null);
        } else {
          setError("No posts found. Please check back soon!");
        }
      } catch (err) {
        console.error("Error loading blog posts:", err);
        setError("Failed to load blog posts. Please try again later.");
      } finally {
        setLoading(false);
      }
    };
    
    loadPosts();
  }, []);

  // Calculate pagination values
  const totalPages = Math.ceil(posts.length / POSTS_PER_PAGE);
  const visiblePosts = posts.slice(
    currentPage * POSTS_PER_PAGE,
    (currentPage + 1) * POSTS_PER_PAGE
  );

  // Handlers for navigating between pages
  const handlePrev = () => {
    setCurrentPage((prev) => Math.max(prev - 1, 0));
  };

  const handleNext = () => {
    setCurrentPage((prev) => Math.min(prev + 1, totalPages - 1));
  };

  return (
    <div className={styles.container}>
      {/* Using grid layout similar to resume page for consistency */}
      <div className={styles.blogLayout}>
        <div className={styles.mainContent}>
          {loading ? (
            <div className={styles.loadingState}>
              <p>Loading blog posts...</p>
            </div>
          ) : error ? (
            <div className={styles.errorState}>
              <p>{error}</p>
            </div>
          ) : visiblePosts.length > 0 ? (
            <>
              {visiblePosts.map((post) => (
                <BlogPost
                  key={post.id}
                  id={post.id}
                  title={post.title}
                  date={post.date}
                  description={post.description}
                  tags={post.tags}
                  content={post.content}
                />
              ))}
              
              {totalPages > 1 && (
                <Pagination
                  currentPage={currentPage}
                  totalPages={totalPages}
                  onPrevPage={handlePrev}
                  onNextPage={handleNext}
                />
              )}
            </>
          ) : (
            <p>No blog posts available at this time. Check back soon!</p>
          )}
        </div>
        
        {/* Table of Contents as sidebar */}
        {posts.length > 0 && <TableOfContents posts={posts} />}
      </div>
    </div>
  );
};

export default Blog;
