// src/components/blog/TableOfContents.js
import React from 'react';
import styles from '../../styles/pages/Blog.module.css';

/**
 * Table of contents component for the blog sidebar
 * Matches the styling of the resume sidebar
 * 
 * @param {Object} props - Component props 
 * @param {Array} props.posts - Array of post objects with id, title, date
 */
export function TableOfContents({ posts }) {
  return (
    <div className={styles.blogSidebar}>
      <div className={styles.sidebarContent}>
        <h3>Table of Contents</h3>
        <ul className={styles.tocList}>
          {posts.map((post) => (
            <li key={post.id} className={styles.tocItem}>
              <a href={`#post-${post.id}`}>
                {post.title}
                <span className={styles.tocDate}>{post.date}</span>
              </a>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}