/**
 * Utility functions for blog post handling
 * Optimized for deployment to GitHub Pages
 */

/**
 * Parses frontmatter metadata from markdown content
 * @param {string} content - Raw markdown content
 * @returns {Object} - Object with metadata and content properties
 */
export function parseMarkdownWithFrontmatter(content) {
  // Check if content has frontmatter (starts with ---)
  if (!content.startsWith('---')) {
    return { metadata: {}, content };
  }

  // Find the end of frontmatter section
  const endOfFrontmatter = content.indexOf('---', 3);
  if (endOfFrontmatter === -1) {
    return { metadata: {}, content };
  }

  // Extract and parse frontmatter
  const frontmatter = content.slice(3, endOfFrontmatter).trim();
  const metadata = {};
  
  frontmatter.split('\n').forEach(line => {
    const [key, ...valueParts] = line.split(':');
    if (key && valueParts.length) {
      const value = valueParts.join(':').trim();
      
      // Handle arrays in tags format [tag1, tag2, tag3]
      if (key.trim() === 'tags' && value.startsWith('[') && value.endsWith(']')) {
        metadata.tags = value
          .slice(1, -1)
          .split(',')
          .map(tag => tag.trim());
      } else {
        metadata[key.trim()] = value;
      }
    }
  });

  // Return metadata and content separately
  const contentWithoutFrontmatter = content.slice(endOfFrontmatter + 3).trim();
  return { metadata, content: contentWithoutFrontmatter };
}

/**
 * Fetches blog posts with improved error handling for GitHub Pages deployment
 * Uses relative paths and has fallback mechanisms
 */
export async function fetchPosts() {
  try {
    // Try the main path first, then fallback to relative paths
    const manifestPaths = [
      "/posts/manifest.json",
      "./posts/manifest.json",
      "../posts/manifest.json"
    ];
    
    let manifestResponse = null;
    let manifest = null;
    
    // Try each path until successful
    for (const path of manifestPaths) {
      try {
        manifestResponse = await fetch(path);
        if (manifestResponse.ok) {
          manifest = await manifestResponse.json();
          console.log("Successfully loaded manifest from:", path);
          break;
        }
      } catch (err) {
        console.warn(`Could not load manifest from ${path}:`, err);
      }
    }
    
    if (!manifest || !manifest.posts) {
      console.error("Could not load manifest from any path");
      return [];
    }
    
    const postFilenames = manifest.posts;
    
    // Map each filename to a post object
    const postPromises = postFilenames.map(async (filename) => {
      // Try different path formats to resolve GitHub Pages path issues
      const possiblePaths = [
        `/posts/${filename}`,
        `./posts/${filename}`,
        `../posts/${filename}`
      ];
      
      let response = null;
      let rawContent = null;
      
      // Try each path until we get content
      for (const path of possiblePaths) {
        try {
          response = await fetch(path);
          if (response.ok) {
            rawContent = await response.text();
            console.log("Successfully loaded post from:", path);
            break;
          }
        } catch (err) {
          console.warn(`Could not load post from ${path}:`, err);
        }
      }
      
      if (!rawContent) {
        console.error(`Failed to load content for ${filename}`);
        return null;
      }
      
      // Parse the content
      const { metadata, content } = parseMarkdownWithFrontmatter(rawContent);
      
      // Remove the .md extension
      const baseName = filename.replace(".md", "");
      // Split the filename into date and title parts
      const [dateStr, ...titleParts] = baseName.split("_");
      
      // Convert the hyphenated title into a space-separated title
      const titleFromFilename = titleParts.join(" ").replace(/-/g, " ");
      
      // Reformat the date from MMDDYYYY to YYYY-MM-DD
      const month = dateStr.substring(0, 2);
      const day = dateStr.substring(2, 4);
      const year = dateStr.substring(4);
      const dateFromFilename = `${year}-${month}-${day}`;

      return {
        id: baseName,
        title: metadata.title || titleFromFilename,
        date: metadata.date || dateFromFilename,
        description: metadata.description || '',
        tags: metadata.tags || [],
        content,
      };
    });

    // Filter out null posts and sort by date
    const posts = (await Promise.all(postPromises))
      .filter(post => post !== null)
      .sort((a, b) => new Date(b.date) - new Date(a.date));
      
    return posts;
  } catch (error) {
    console.error("Error fetching posts:", error);
    return [];
  }
}
